// Standalone clone of PMFS Utils::ExpectedValue(grid, 0.05) endpoint semantics.
//
// Input CSV is generated by tnqc_vgr_fixed_trajectory_replay.py with columns:
// cell_index,grid_i,grid_j,x,y,source_probability
//
// The important detail is intentional: cells are first arranged in the same
// y-major/x-minor order used by Math.cpp, then std::sort compares probability
// only, exactly like PMFS.  This preserves the native implementation's
// equal-probability tie behavior instead of inventing a Python tie-break.
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace
{
    struct InputRow
    {
        int gridX = 0;
        int gridY = 0;
        double x = 0.0;
        double y = 0.0;
        double probability = 0.0;
    };

    struct CellData
    {
        int gridX = 0;
        int gridY = 0;
        double probability = 0.0;
    };

    std::vector<std::string> splitCsv(const std::string& line)
    {
        std::vector<std::string> out;
        std::stringstream ss(line);
        std::string field;
        while (std::getline(ss, field, ','))
            out.push_back(field);
        return out;
    }
}

int main(int argc, char** argv)
{
    if (argc != 4)
    {
        std::cerr << "usage: tnqc_expected_value_eval <posterior.csv> <truth_x> <truth_y>\n";
        return 2;
    }

    const std::string path = argv[1];
    const double truthX = std::stod(argv[2]);
    const double truthY = std::stod(argv[3]);

    std::ifstream file(path);
    if (!file.is_open())
        throw std::runtime_error("cannot open posterior csv: " + path);

    std::string line;
    if (!std::getline(file, line))
        throw std::runtime_error("empty posterior csv");
    if (line != "cell_index,grid_i,grid_j,x,y,source_probability")
        throw std::runtime_error("unexpected posterior csv header: " + line);

    std::vector<InputRow> input;
    while (std::getline(file, line))
    {
        if (line.empty())
            continue;
        const auto f = splitCsv(line);
        if (f.size() != 6)
            throw std::runtime_error("malformed posterior csv row: " + line);
        InputRow r;
        r.gridX = std::stoi(f[1]);
        r.gridY = std::stoi(f[2]);
        r.x = std::stod(f[3]);
        r.y = std::stod(f[4]);
        r.probability = std::stod(f[5]);
        if (!std::isfinite(r.probability) || r.probability < 0.0)
            throw std::runtime_error("invalid posterior probability");
        input.push_back(r);
    }
    if (input.empty())
        throw std::runtime_error("posterior csv has no free cells");

    // Math.cpp builds CellData with y as the outer loop and x as the inner.
    std::sort(input.begin(), input.end(), [](const InputRow& a, const InputRow& b)
    {
        if (a.gridY != b.gridY)
            return a.gridY < b.gridY;
        return a.gridX < b.gridX;
    });

    std::vector<CellData> data;
    data.reserve(input.size());
    std::map<std::pair<int, int>, std::pair<double, double>> coordinates;
    for (const InputRow& r : input)
    {
        data.push_back({r.gridX, r.gridY, r.probability});
        coordinates[{r.gridX, r.gridY}] = {r.x, r.y};
    }

    // This comparator and loop intentionally mirror
    // GSL::Utils::ExpectedValue in Common/Utils/Math.cpp.
    std::sort(data.begin(), data.end(), [](const CellData& a, const CellData& b)
    {
        return a.probability > b.probability;
    });

    double averageX = 0.0;
    double averageY = 0.0;
    double sum = 0.0;
    int selected = 0;
    for (int i = 0; i < data.size() * 0.05; ++i)
    {
        const CellData& cd = data.at(static_cast<std::size_t>(i));
        const auto coord = coordinates.at({cd.gridX, cd.gridY});
        averageX += cd.probability * coord.first;
        averageY += cd.probability * coord.second;
        sum += cd.probability;
        ++selected;
    }
    if (!(sum > 0.0) || !std::isfinite(sum))
        throw std::runtime_error("invalid top-5% probability mass");

    averageX /= sum;
    averageY /= sum;
    const double error = std::hypot(averageX - truthX, averageY - truthY);

    std::cout << std::setprecision(17)
              << "{\"pmfs_top5_x\":" << averageX
              << ",\"pmfs_top5_y\":" << averageY
              << ",\"pmfs_top5_error_m\":" << error
              << ",\"pmfs_top5_cell_count\":" << selected
              << "}\n";
    return 0;
}
